using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF8 discriminator property name so existing 500K documents
            // (which store "Discriminator") remain readable and direct SQL queries
            // referencing c.Discriminator continue to work.
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF8 compound id format ("Product|123") so existing documents
            // remain accessible via FindAsync / point-reads.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // Removed HasIndex — EF Core 9 Cosmos provider throws at startup for
        // HasIndex calls. Cosmos DB indexing is managed via the container's
        // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

